{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Tasimelteon, the closest analogue (Morgan 0.49), has absolute oral bioavailability of 38% in humans, above the 20% threshold; this is contradictory to a low prediction, but its cyclopropane-benzofuran scaffold differs from the query's ethylene-linked tricyclic indeno-furan core.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Darifenacin, which contains a 2,3-dihydrobenzofuran-ethylamine motif related to the query, has very low oral bioavailability of 15–19% in humans due to low solubility and high first-pass metabolism, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "MK-458, a tricyclic fused-ether dopamine agonist, has absolute oral bioavailability of approximately 5% in patients, well below the 20% threshold, supporting a low-F phenotype for the query's fused ether scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Eliglustat, a lipophilic amide/amine with moderate molecular weight, has simulated absolute oral bioavailability of 8.6%, below threshold, indicating that favorable physicochemical properties do not guarantee high F when first-pass metabolism is substantial.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Prediction is low. Although the closest analogue tasimelteon has 38% F, the query is ramelteon, whose tricyclic indeno-furan core and ethylene linker are associated with extensive first-pass metabolism; lower-similarity but mechanistically relevant analogues (darifenacin 15–19%, MK-458 ~5%, eliglustat 8.6%) affirm that F is below 20%. The physicochemical prior is overridden by these experimental and metabolic considerations.",
  "evidence_gaps": [
    "No direct ramelteon bioavailability record is present in the provided evidence set; the closest analogue (tasimelteon) is high, so the low prediction relies on lower-similarity low-F analogues and known clinical data for ramelteon.",
    "First-pass metabolism and CYP-mediated clearance are not captured by the physicochemical prior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

